<script setup>
import {reactive} from 'vue'; import {Head,router,usePage} from '@inertiajs/vue3'; import AppLayout from '../../Layouts/AppLayout.vue'; import PageBanner from '../../Components/PageBanner.vue';
defineOptions({layout:AppLayout}); const p=defineProps({shipments:Array,locations:Array,can_receive:Boolean}); const errors=usePage().props.errors; const localNow=()=>{const d=new Date(Date.now()-new Date().getTimezoneOffset()*60000); return d.toISOString().slice(0,16)}; const forms=reactive({}); const form=s=>forms[s.id]??={idempotency_key:crypto.randomUUID(),vendor_do_number:s.document_no,received_at:localNow(),lines:s.lines.map(l=>({enabled:true,refill_line_id:l.refill_line_id,location_id:'',quantity:l.quantity}))}; const submit=s=>{const f=form(s);router.post(s.receipt_url,{...f,lines:f.lines.filter(x=>x.enabled).map(({refill_line_id,location_id,quantity})=>({refill_line_id,location_id,quantity}))})};
</script>
<template><Head title="Incoming Refill"/><div class="units-page"><PageBanner title="Incoming Refill" description="Masukkan quantity fisik dalam satuan bulat; hanya posting ini yang menambah stok Consignment." icon="arrowDown"/><div v-if="Object.keys(errors).length" class="field-error" role="alert"><strong>Penerimaan belum berhasil.</strong><ul><li v-for="(e,k) in errors" :key="k">{{e}}</li></ul></div><section v-for="s in shipments" :key="s.id" class="surface-card form-card"><form v-if="can_receive" class="form-card__body form-stack" @submit.prevent="submit(s)"><h2>{{s.refill}} · {{s.vendor}}</h2><p>{{s.document_no}} · {{s.status}}</p><input v-model="form(s).vendor_do_number" class="form-input" required/><input v-model="form(s).received_at" class="form-input" type="datetime-local" required/><div v-for="x in form(s).lines" :key="x.refill_line_id" class="form-grid"><label><input v-model="x.enabled" type="checkbox"/> {{s.lines.find(l=>l.refill_line_id===x.refill_line_id)?.item}}</label><div><input v-model="x.quantity" class="form-input" type="number" min="1" step="1" :disabled="!x.enabled" required/><select v-model="x.location_id" class="form-input" :disabled="!x.enabled" required><option value="">Pilih lokasi</option><option v-for="l in locations" :key="l.id" :value="l.id">{{l.location_code}} · {{l.location_name}}</option></select></div></div><button class="button button--primary" :disabled="!form(s).lines.some(x=>x.enabled)">Posting penerimaan</button></form><div v-else class="form-card__body"><h2>{{s.refill}} · {{s.vendor}}</h2><p>{{s.document_no}} · {{s.status}} · Warehouse yang dapat memposting penerimaan.</p></div></section><section v-if="!shipments.length" class="surface-card"><p class="page-note">Belum ada pengiriman Vendor yang menunggu penerimaan.</p></section></div></template>
